<?php
declare(strict_types=1);
use Vendi\Database\Connection;use Vendi\Http\ApiGuard;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json');
try{$u=ApiGuard::session();ApiGuard::csrf();$d=json_decode(file_get_contents('php://input'),true)?:[];$type=(string)($d['type']??'');$amount=(float)($d['amount']??0);if(!in_array($type,['deposit','withdrawal'],true)||$amount<=0)throw new RuntimeException('Movimiento inválido');$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);ApiGuard::permission($db,$u,'cash.movements');$q=$db->prepare("SELECT id FROM cash_sessions WHERE business_id=? AND branch_id=? AND user_id=? AND status='open' ORDER BY id DESC LIMIT 1");$q->execute([(int)$u['business_id'],(int)$u['default_branch_id'],(int)$u['id']]);$sid=$q->fetchColumn();if(!$sid)throw new RuntimeException('No hay caja abierta');$i=$db->prepare("INSERT INTO cash_movements(business_id,branch_id,cash_session_id,user_id,type,amount,note) VALUES(?,?,?,?,?,?,?)");$i->execute([(int)$u['business_id'],(int)$u['default_branch_id'],$sid,(int)$u['id'],$type,$amount,substr((string)($d['note']??''),0,255)]);echo json_encode(['ok'=>true]);}catch(Throwable $e){http_response_code(422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}